using System;
using EmberBastion;
class BossTelegraphChecks {static int n;static void Check(bool v,string m){n++;if(!v)throw new Exception(m);}static void Main(){var b=new Battle(7,0);Check(b.Place(0,0),"place");b.Wave=4;Check(b.Start(),"boss wave");int ticks=0;while(b.Enemies.Find(e=>e.Kind==4)==null&&ticks++<600)b.Step(1.0/60);var boss=b.Enemies.Find(e=>e.Kind==4);Check(boss!=null,"boss spawned");boss.NextCharge=1.51;var replay=Battle.ImportCombat(b.ExportCombat());var copied=b.CopyCombat();b.Step(1.0/60);replay.Step(1.0/60);copied.Step(1.0/60);Check(b.Cues.Exists(c=>c.Kind=="warn")&&replay.Cues.Exists(c=>c.Kind=="warn")&&copied.Cues.Exists(c=>c.Kind=="warn"),"warning appears across saves");Check(boss.NextCharge<=1.5&&boss.NextCharge>0&&boss.Charge==0,"warning state");int warnings=0;for(int i=0;i<100;i++){b.Step(1.0/60);if(b.Cues.Exists(c=>c.Kind=="warn"))warnings++;}Check(warnings==0,"warning not repeated");Check(boss.Charge>0&&boss.NextCharge>8,"charge begins after warning");Console.WriteLine("PASS "+n+" boss warning, charge and saved-state checks");}}
